INSERT INTO route_stops (route_id,name,status,owner,metric,priority,location,stop_order) SELECT ((n-1) % 8)+1, CONCAT('Stop ', n), IF(n % 5=0,'Delayed','Planned'), 'Planning', CONCAT('Window ', n), IF(n % 5=0,'High','Normal'), CONCAT('Dock ', n), n FROM (SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13 UNION SELECT 14 UNION SELECT 15 UNION SELECT 16 UNION SELECT 17 UNION SELECT 18 UNION SELECT 19 UNION SELECT 20) x;
INSERT INTO jobs (name,status,owner,metric,priority,location,customer_id,pickup_window,delivery_window) SELECT CONCAT('JOB-',1000+n), ELT((n % 6)+1,'Unassigned','Assigned','En Route','At Stop','Completed','Delayed / Exception'), 'Maya Chen', CONCAT('$', 850+n*37, ' revenue'), IF(n % 6=5,'High','Normal'), ELT((n % 6)+1,'Chicago','Milwaukee','Detroit','Dallas','Columbus','Cincinnati'), ((n-1)%6)+1, '08:00-10:00','14:00-18:00' FROM (SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13 UNION SELECT 14 UNION SELECT 15 UNION SELECT 16 UNION SELECT 17 UNION SELECT 18 UNION SELECT 19 UNION SELECT 20 UNION SELECT 21 UNION SELECT 22 UNION SELECT 23 UNION SELECT 24 UNION SELECT 25) x;
